"""Channel model."""

from dataclasses import dataclass

from sqlalchemy import BigInteger, ForeignKey, String, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from bot.db.base import Base, TimestampMixin


class Channel(TimestampMixin, Base):
    """Telegram channels added by users."""

    __tablename__ = "channels"
    __table_args__ = (UniqueConstraint("user_id", "channel_name"),)

    # Internal surrogate primary key, generated by the database.
    id: Mapped[int] = mapped_column(BigInteger, primary_key=True, autoincrement=True)

    # External Telegram channel ID; comes from Telegram, never generated by us.
    channel_id: Mapped[int] = mapped_column(BigInteger, unique=True)
    channel_name: Mapped[str] = mapped_column(String(128))
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), index=True)

    def __repr__(self) -> str:
        return f"Channel(id={self.id}, channel_name={self.channel_name!r})"


@dataclass(frozen=True, kw_only=True, slots=True)
class ChannelCreateData:
    channel_id: int
    channel_name: str
    user_id: int
